-- Amazon offers for the Phase 2 ranking pages (/es/mejores/omega-3/, /de/vergleich/kollagen-pulver/, /de/vergleich/ashwagandha/).
-- Generated from src/content/rankings/*.md on 2026-10-30. Applied to nutrimetrics-db by hand (idempotent). Retailers 2/3 come from ranking_offers.sql.
-- Products: 9123-9133 ES omega-3, 9217-9228 DE collagen powder, 9229-9240 DE ashwagandha. price = 0 means 'not tracked'.
PRAGMA foreign_keys = ON;

ON CONFLICT(id) DO UPDATE SET brand = excluded.brand, name = excluded.name, pack_label = excluded.pack_label, verified = excluded.verified, source_url = excluded.source_url, updated_at = datetime('now');

ON CONFLICT(id) DO UPDATE SET product_id = excluded.product_id, retailer_id = excluded.retailer_id, country = excluded.country, merchant_url = excluded.merchant_url, checked_at = excluded.checked_at;
